// Bloom service worker — static build.
// Served as a plain asset from /sw.js (previously generated by server.ts).
// Push events still work if a push provider is ever added; local notifications
// triggered from the page work without any server.

self.addEventListener('install', function () {
  self.skipWaiting();
});

self.addEventListener('activate', function (event) {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', function (event) {
  let data = {};
  if (event.data) {
    try {
      data = event.data.json();
    } catch (e) {
      data = { title: '🌱 Bloom Check-in', body: event.data.text() };
    }
  }

  const title = data.title || '🌱 Bloom Check-in';
  const options = {
    body: data.body || 'Time for your daily Bloom check-in! Keep your streak growing. 🌸',
    icon: '/favicon.ico',
    badge: '/favicon.ico',
    tag: 'bloom-daily-reminder',
    renotify: true,
    data: data.data || {}
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', function (event) {
  event.notification.close();
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function (clientList) {
      for (var i = 0; i < clientList.length; i++) {
        var client = clientList[i];
        if (client.url.indexOf(self.location.origin) !== -1 && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) {
        return clients.openWindow('/');
      }
    })
  );
});
